def calculate_n(a, b, c):
    S = a + b + c
    P2 = a*b + b*c + c*a
    numerator = S * P2 + S
    denominator = 4 * a * b * c

    # Check if the division results in an integer
    if denominator == 0:
        return None

    if numerator % denominator == 0:
        return numerator // denominator
    else:
        return None

results = {}
for a in range(1, 11):
    for b in range(a + 1, 11):
        for c in range(b + 1, 11):
            n = calculate_n(a, b, c)
            if n is not None:
                triple = (a, b, c)
                if n not in results:
                    results[n] = []
                results[n].append(triple)

# Print results in a structured way
print("Integer values of n found:")
sorted_n = sorted(results.keys())
for n in sorted_n:
    print(f"n = {n}: produced by {results[n]}")

# List all found n values for easy review
all_n_values = list(results.keys())
print(f"\nAll distinct integer n values found: {all_n_values}")

