def check_n(b, c, n):
    # n = ((1+b+c)(b+c+bc+1) + 1) / (4bc)
    # Using the derived equation: (b+c+1)(b+c+bc+1) = 4n bc

    LHS = (b + c + 1) * (b + c + b * c + 1)
    RHS = 4 * n * b * c

    return LHS == RHS

